    [Fact]
    public void ResponsesMatchRealPlc()
    {
        var profile = CpuProfiles.Get(CpuProfiles.IqR).With("R08PCPU", 0x4841, new Dictionary<string, uint> { ["D"] = 18432, ["M"] = 12288, ["S"] = 1024 });
        var settings = new PlcSettings { Units = new ushort[] { 0x1F }, Networks = new byte[] { 5 } };
        var engine = new SlmpEngine(new PlcModel(profile, settings, new LabelDefinitions()));
        var n = 0;
        foreach (var (name, request, expected) in Measured)
        {
            var session = new SlmpSession($"conn{n++}", "TEST");
            var actual = Convert.ToHexString(engine.Process(FrameCodec.Parse(Convert.FromHexString(request)), session).Frame!);
            Assert.True(expected == actual, $"{name}: 実機 {expected} / Sim {actual}");
        }
    }
